    }
    map['lamb'] = Variable<int>(lamb);
    map['season'] = Variable<int>(season);
    if (!nullToAbsent || rearingDam != null) {
      map['rearing_dam'] = Variable<int>(rearingDam);
    }
    map['outcome'] = Variable<String>(outcome);
    if (!nullToAbsent || corrects != null) {
