class LambRearingData extends DataClass {
  final int lambId;
  final int birthDam;
  final int? rearingDam;
  final bool wasFostered;
  const LambRearingData({
    required this.lambId,
    required this.birthDam,
    this.rearingDam,
    required this.wasFostered,
  });
  factory LambRearingData.fromJson(Map<String, dynamic> json, {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return LambRearingData(
      lambId: serializer.fromJson<int>(json['lamb_id']),
      birthDam: serializer.fromJson<int>(json['birth_dam']),
      rearingDam: serializer.fromJson<int?>(json['rearing_dam']),
      wasFostered: serializer.fromJson<bool>(json['was_fostered']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'lamb_id': serializer.toJson<int>(lambId),
      'birth_dam': serializer.toJson<int>(birthDam),
      'rearing_dam': serializer.toJson<int?>(rearingDam),
      'was_fostered': serializer.toJson<bool>(wasFostered),
    };
  }

  LambRearingData copyWith({
    int? lambId,
    int? birthDam,
    Value<int?> rearingDam = const Value.absent(),
    bool? wasFostered,
  }) => LambRearingData(
    lambId: lambId ?? this.lambId,
    birthDam: birthDam ?? this.birthDam,
    rearingDam: rearingDam.present ? rearingDam.value : this.rearingDam,
    wasFostered: wasFostered ?? this.wasFostered,
  );
  @override
  String toString() {
    return (StringBuffer('LambRearingData(')
          ..write('lambId: $lambId, ')
          ..write('birthDam: $birthDam, ')
          ..write('rearingDam: $rearingDam, ')
          ..write('wasFostered: $wasFostered')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(lambId, birthDam, rearingDam, wasFostered);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is LambRearingData &&
          other.lambId == this.lambId &&
          other.birthDam == this.birthDam &&
          other.rearingDam == this.rearingDam &&
          other.wasFostered == this.wasFostered);
}

