        occupancyId: row.readNullable<int>('occupancy_id'),
        eweId: row.readNullable<int>('ewe_id'),
        eweTag: row.readNullable<String>('ewe_tag'),
        enteredAt: NullAwareTypeConverter.wrapFromSql(
          $PenOccupanciesTable.$converterenteredAt,
          row.readNullable<int>('entered_at'),
        ),
      ),
    );
  }

  Selectable<InThePensResult> inThePens() {
    return customSelect(
      'SELECT o.id AS occupancy_id, o.pen AS pen_id, p.label AS pen_label, o.ewe AS ewe_id, e.tag AS ewe_tag, o.entered_at AS entered_at FROM pen_occupancies AS o JOIN pens AS p ON p.id = o.pen LEFT JOIN ewes AS e ON e.id = o.ewe WHERE o.exited_at IS NULL AND o.struck = 0 ORDER BY o.entered_at',
      variables: [],
      readsFrom: {penOccupancies, pens, ewes},
    ).map(
      (QueryRow row) => InThePensResult(
        occupancyId: row.read<int>('occupancy_id'),
        penId: row.read<int>('pen_id'),
        penLabel: row.read<String>('pen_label'),
        eweId: row.readNullable<int>('ewe_id'),
        eweTag: row.readNullable<String>('ewe_tag'),
        enteredAt: $PenOccupanciesTable.$converterenteredAt.fromSql(row.read<int>('entered_at')),
      ),
    );
  }

  Selectable<EarlierAnimalsWithTagResult> earlierAnimalsWithTag(String tag) {
    return customSelect(
      'SELECT e.id AS ewe_id, e.tag AS tag, e.status AS status, e.created_at AS created_at FROM ewes AS e WHERE e.tag = ?1 AND e.status <> \'active\' ORDER BY e.created_at DESC',
      variables: [Variable<String>(tag)],
      readsFrom: {ewes},
    ).map(
      (QueryRow row) => EarlierAnimalsWithTagResult(
        eweId: row.read<int>('ewe_id'),
        tag: row.read<String>('tag'),
        status: row.read<String>('status'),
        createdAt: $EwesTable.$convertercreatedAt.fromSql(row.read<int>('created_at')),
      ),
    );
  }

  Future<int> sweepSearchDocs() {
    return customUpdate(
      'DELETE FROM search_docs WHERE(subject_kind = \'note\' AND subject_id NOT IN (SELECT id FROM notes))OR(subject_kind = \'ewe\' AND subject_id NOT IN (SELECT id FROM ewes))OR(subject_kind = \'lambing\' AND subject_id NOT IN (SELECT id FROM lambings))OR(subject_kind = \'lamb\' AND subject_id NOT IN (SELECT id FROM lambs))OR(subject_kind = \'treatment\' AND subject_id NOT IN (SELECT id FROM treatments))',
      variables: [],
      updates: {},
    );
  }

  Future<int> rebuildSearchIndex() {
    return customInsert(
      'INSERT INTO search_fts (search_fts) VALUES (\'rebuild\')',
      variables: [],
      updates: {},
    );
  }

  Selectable<SearchAllResult> searchAll(String query, int limit) {
    return customSelect(
      'SELECT d.id AS doc_id, d.subject_kind AS subject_kind, d.subject_id AS subject_id, d.ewe_id AS ewe_id, d.season_id AS season_id, d.title AS title, d.occurred_at AS occurred_at, snippet(search_fts, 1, \'[\', \']\', \'…\', 12) AS snippet FROM search_fts AS f JOIN search_docs AS d ON d.id = f."rowid" WHERE search_fts MATCH ?1 ORDER BY bm25(search_fts), d.occurred_at DESC LIMIT ?2',
      variables: [Variable<String>(query), Variable<int>(limit)],
      readsFrom: {searchDocs, searchFts},
    ).map(
      (QueryRow row) => SearchAllResult(
        docId: row.read<int>('doc_id'),
        subjectKind: row.read<String>('subject_kind'),
        subjectId: row.read<int>('subject_id'),
        eweId: row.readNullable<int>('ewe_id'),
        seasonId: row.readNullable<int>('season_id'),
        title: row.read<String>('title'),
        occurredAt: row.read<int>('occurred_at'),
        snippet: row.readNullable<String>('snippet'),
      ),
    );
  }

