class PenBoardResult {
  final int penId;
  final String penLabel;
  final int sortOrder;
  final int? occupancyId;
  final int? eweId;
  final String? eweTag;
  final Instant? enteredAt;
  PenBoardResult({
    required this.penId,
    required this.penLabel,
    required this.sortOrder,
    this.occupancyId,
    this.eweId,
    this.eweTag,
    this.enteredAt,
  });
  @override
  int get hashCode =>
      Object.hash(penId, penLabel, sortOrder, occupancyId, eweId, eweTag, enteredAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is PenBoardResult &&
          other.penId == this.penId &&
          other.penLabel == this.penLabel &&
          other.sortOrder == this.sortOrder &&
          other.occupancyId == this.occupancyId &&
          other.eweId == this.eweId &&
          other.eweTag == this.eweTag &&
          other.enteredAt == this.enteredAt);
  @override
  String toString() {
    return (StringBuffer('PenBoardResult(')
          ..write('penId: $penId, ')
          ..write('penLabel: $penLabel, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('occupancyId: $occupancyId, ')
          ..write('eweId: $eweId, ')
          ..write('eweTag: $eweTag, ')
          ..write('enteredAt: $enteredAt')
          ..write(')'))
        .toString();
  }
}

